// An ungranted dependency. It never touches the env op itself; it borrows the
// deputy's authority by calling the deputy, which does the privileged read. The
// deputy's frame is nearest on the stack, so nearest-frame attribution would
// attribute the read to the granted deputy and allow it. evil-dep's own frame
// is live one level down, so stack-intersection sees it and denies.
import { readEnv } from "../deputy-dep/index.js";

export function launder(name) {
  return readEnv(name);
}
